def seed_layer_configs(apps, schema_editor):
    """删除 cells_per_layer 前，把每个档案柜的统一格数展开为逐层记录。"""
    Cabinet = apps.get_model("archive", "Cabinet")
    CabinetLayer = apps.get_model("archive", "CabinetLayer")
    layers_to_create = []
    for cab in Cabinet.objects.all():
        for no in range(1, int(cab.layers) + 1):
            layers_to_create.append(
                CabinetLayer(cabinet=cab, layer_no=no, cells=cab.cells_per_layer)
            )
    CabinetLayer.objects.bulk_create(layers_to_create)


def unseed_layer_configs(apps, schema_editor):
    """反迁移：按层记录恢复统一格数（取第 1 层），再删层记录。"""
    Cabinet = apps.get_model("archive", "Cabinet")
    CabinetLayer = apps.get_model("archive", "CabinetLayer")
    for cab in Cabinet.objects.all():
        first = cab.layer_configs.order_by("layer_no").first()
        if first:
            cab.cells_per_layer = first.cells
            cab.save(update_fields=["cells_per_layer"])
    CabinetLayer.objects.all().delete()


